<?php require 'config.php';$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$sql='SELECT c.*,ca.name category FROM cakes c JOIN categories ca ON ca.id=c.category_id WHERE c.active=1';$p=[];if(!empty($_GET['q'])){$sql.=' AND (c.name LIKE ? OR c.flavor LIKE ?)';$p[]='%'.$_GET['q'].'%';$p[]='%'.$_GET['q'].'%';}if(!empty($_GET['category'])){$sql.=' AND c.category_id=?';$p[]=(int)$_GET['category'];}if(isset($_GET['min'])&&$_GET['min']!==''){$sql.=' AND c.price>=?';$p[]=(float)$_GET['min'];}if(isset($_GET['max'])&&$_GET['max']!==''){$sql.=' AND c.price<=?';$p[]=(float)$_GET['max'];}$sql.=' ORDER BY c.name';$s=$pdo->prepare($sql);$s->execute($p);$cakes=$s->fetchAll();?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><header><strong>Sweet Treats</strong><nav><a href="index.php">Home</a><a href="cart.php">Cart</a><a href="dashboard.php">Dashboard</a></nav></header><div class="wrap"><div class="card"><h1>Search and filter cakes</h1><form class="grid"><input name="q" placeholder="Search cake or flavor" value="<?=h($_GET['q']??'')?>"><select name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=((string)($c['id'])===($_GET['category']??''))?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><input type="number" name="min" placeholder="Minimum price" value="<?=h($_GET['min']??'')?>"><input type="number" name="max" placeholder="Maximum price" value="<?=h($_GET['max']??'')?>"><button>Apply filters</button></form></div><div class="grid"><?php foreach($cakes as $c):?><div class="card cake"><?php if($c['image']&&file_exists(__DIR__.'/'.$c['image'])):?><img src="<?=h($c['image'])?>" alt="<?=h($c['name'])?>"><?php else:?><div class="placeholder">🍰</div><?php endif;?><h3><?=h($c['name'])?></h3><p><?=h($c['category'])?> · <?=h($c['flavor'])?></p><p class="price"><?=money($c['price'])?></p><a class="btn" href="cake.php?id=<?=$c['id']?>">View details</a></div><?php endforeach;?></div></div></body></html>